from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by LCS length with s, modulo 998244353.

    The n bits of a state encode consecutive differences in an LCS DP row.
    Appending one character updates that row using the bit-parallel LCS rule.
    """
    mod = 998244353
    positions = {}
    for i, ch in enumerate(s):
        positions[ch] = positions.get(ch, 0) | (1 << i)

    size = 1 << n
    transitions = []
    absent = 26 - len(positions)
    for state in range(size):
        counts = {state: absent} if absent else {}
        for matches in positions.values():
            x = state | matches
            following = x & ~(x - ((state << 1) | 1))
            counts[following] = counts.get(following, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        next_dp = [0] * size
        for state, ways in enumerate(dp):
            if ways:
                for following, multiplicity in transitions[state]:
                    next_dp[following] = (
                        next_dp[following] + ways * multiplicity
                    ) % mod
        dp = next_dp

    answer = [0] * (n + 1)
    for state, ways in enumerate(dp):
        k = state.bit_count()
        answer[k] = (answer[k] + ways) % mod
    return answer

