"""Good-product sequence counting via multiplicative summation.

The arithmetic kernel is compiled once with the system C++ compiler because
the largest inputs exceed the five-second release limit in pure Python.
"""
import ctypes
import shutil
import subprocess
import tempfile
from pathlib import Path

_SOURCE = "
#include <vector>
#include <cmath>
#include <utility>
#include <algorithm>
using ll=long long;
const ll MOD=998244353;
struct Counter {
 ll n,m; int r;
 std::vector<ll> pc,ch,coef;
 std::vector<int> primes,pref;
 int at(ll x){return x<=r?int(x):r+int(n/x);}
 ll power(ll a,ll b){ll z=1;for(;b;b>>=1,a=a*a%MOD)if(b&1)z=z*a%MOD;return z;}
 std::pair<ll,ll> sums(ll x,int start){
  int k=at(x);
  ll total=m*(pc[k]-start)%MOD;
  ll bad=m*((pc[k]+ch[k]+(x>=3))/2-pref[start])%MOD;
  for(int i=start;i<(int)primes.size();++i){
   ll p=primes[i];if(p*p>x)break;
   ll pe=p;int e=1,residue=p%3;
   while(pe<=x/p){
    ll q=x/pe,st,sb;
    if(i+1==(int)primes.size()||1LL*primes[i+1]*primes[i+1]>q){
     int t=at(q);
     st=m*(pc[t]-i-1)%MOD;
     sb=m*((pc[t]+ch[t]+(q>=3))/2-pref[i+1])%MOD;
    }else{auto z=sums(q,i+1);st=z.first;sb=z.second;}
    total=(total+coef[e]*st+coef[e+1])%MOD;
    if(residue==0||(residue==1&&e%3!=2)||(residue==2&&e%2==0))
     bad=(bad+coef[e]*sb)%MOD;
    int ne=e+1;
    if(residue==0||(residue==1&&ne%3!=2)||(residue==2&&ne%2==0))
     bad=(bad+coef[ne])%MOD;
    pe*=p;e=ne;
   }
  }
  return {total,bad};
 }
 ll run(ll N,ll M){
  n=N;m=M;r=std::sqrt((long double)n);
  while(1LL*(r+1)*(r+1)<=n)++r;
  while(1LL*r*r>n)--r;
  pc.resize(2*r+2);ch.resize(2*r+2);
  for(int i=1;i<=r;++i){
   pc[i]=i-1;ch[i]=(i%3==1)-1;
   ll v=n/i;pc[r+i]=v-1;ch[r+i]=(v%3==1)-1;
  }
  std::vector<bool> composite(r+1);
  for(int p=2;p<=r;++p)if(!composite[p]){
   primes.push_back(p);
   if(1LL*p*p<=r)for(int q=p*p;q<=r;q+=p)composite[q]=true;
  }
  for(int p:primes){
   ll square=1LL*p*p,before=pc[p-1],cbefore=ch[p-1];
   int sign=p%3==1?1:(p%3==2?-1:0);
   int limit=std::min((ll)r,n/square);
   for(int i=1;i<=limit;++i){
    int j=at((n/i)/p),k=r+i;
    pc[k]-=pc[j]-before;ch[k]-=sign*(ch[j]-cbefore);
   }
   for(int v=r;v>=square;--v){
    pc[v]-=pc[v/p]-before;ch[v]-=sign*(ch[v/p]-cbefore);
   }
  }
  pref.push_back(0);
  for(int p:primes)pref.push_back(pref.back()+(p%3!=2));
  coef.push_back(1);
  for(int e=1;e<=64;++e)coef.push_back(coef.back()*(m+e-1)%MOD*power(e,MOD-2)%MOD);
  auto z=sums(n,0);return(z.first-z.second+MOD)%MOD;
 }
};
extern "C" long long count_sequences(long long n,long long m){
 if(n<2)return 0;Counter c;return c.run(n,m);
}
"
_kernel = None
_directory = None


def _small_count(N, M):
    """Portable direct multiplicative sieve for small inputs."""
    mod = 998244353
    spf = list(range(N + 1))
    for p in range(2, int(N ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, N + 1, p):
                if spf[v] == v:
                    spf[v] = p
    coefficients = [1]
    for e in range(1, N.bit_length() + 1):
        coefficients.append(coefficients[-1] * (M + e - 1) * pow(e, mod - 2, mod) % mod)
    answer = 0
    for n in range(2, N + 1):
        x, weight, good = n, 1, False
        while x > 1:
            p, e = spf[x], 0
            while x % p == 0:
                x //= p
                e += 1
            weight = weight * coefficients[e] % mod
            good |= (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2)
        if good:
            answer += weight
    return answer % mod


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive sequences whose product is at most N and
    whose product's positive divisor sum is divisible by 3, modulo 998244353.

    Each prime exponent e has binomial(M+e-1,e) assignments to sequence
    positions. Subtract products with no prime power of divisor sum 0 mod 3.
    """
    if N < 2:
        return 0
    if N <= 1000:
        return _small_count(N, M)
    global _kernel, _directory
    if _kernel is None:
        compiler = shutil.which("g++") or shutil.which("c++")
        if compiler is None:
            raise RuntimeError("Large-input counting requires a C++17 compiler")
        _directory = tempfile.TemporaryDirectory(prefix="good_sequences_")
        library = str(Path(_directory.name) / "counter.so")
        build = subprocess.run(
            [compiler, "-O3", "-std=c++17", "-shared", "-fPIC",
             "-x", "c++", "-", "-o", library],
            input=_SOURCE, text=True, capture_output=True, check=False,
        )
        if build.returncode:
            raise RuntimeError("C++ kernel build failed: " + build.stderr)
        _kernel = ctypes.CDLL(library).count_sequences
        _kernel.argtypes = [ctypes.c_longlong, ctypes.c_longlong]
        _kernel.restype = ctypes.c_longlong
    return int(_kernel(N, M))

