from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Given coin denominations, return the k-th smallest distinct amount.

    Each denomination produces its positive multiples. There are infinitely
    many coins of each denomination, but different denominations cannot be
    combined in a single amount.

    Args:
        coins: Distinct positive denominations (1-15 elements, each 1-25).
        k: One-based position of the desired amount, 1 <= k <= 2*10**9.

    Returns:
        The k-th smallest amount that can be made.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a denomination already retained add no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # Collect inclusion-exclusion coefficients by least common multiple.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for divisor, coefficient in coefficients.items():
            multiple = divisor // gcd(divisor, coin) * coin
            changes[multiple] = changes.get(multiple, 0) - coefficient
        for divisor, coefficient in changes.items():
            combined = coefficients.get(divisor, 0) + coefficient
            if combined:
                coefficients[divisor] = combined
            else:
                coefficients.pop(divisor, None)

    low, high = 1, denominations[0] * k
    terms = tuple(coefficients.items())
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Given a tree on vertices 1 through n, return its largest alkane subgraph.

    An alkane is a tree whose vertices all have degree 1 or 4, with at least
    one degree-4 vertex. Return -1 if none exists.
    Runs in O(n) time and space for 1 <= n <= 200000.
    """
    adjacency = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [-1] * n
    order = [0]
    for vertex in order:
        for neighbor in adjacency[vertex]:
            if neighbor != parent[vertex]:
                parent[neighbor] = vertex
                order.append(neighbor)

    # A branch includes its edge to the parent: its root can be a leaf,
    # or can take exactly three child branches to have degree four.
    branch = [1] * n
    answer = -1
    for vertex in reversed(order):
        best = []
        for child in adjacency[vertex]:
            if parent[child] == vertex:
                value = branch[child]
                index = 0
                while index < len(best) and best[index] >= value:
                    index += 1
                best.insert(index, value)
                if len(best) > 4:
                    best.pop()
        if len(best) >= 3:
            branch[vertex] = 1 + sum(best[:3])
            if parent[vertex] != -1:
                # The parent can terminate the subtree as a leaf.
                answer = max(answer, branch[vertex] + 1)
        if len(best) == 4:
            answer = max(answer, 1 + sum(best))
    return answer

